Item.method_code:
/* version: 6*/
/* eslint-disable camelcase */
const _mv_chb = getFieldComponentByName('versioning_discipline');
const item = document.item;
const _isVers = (aras.getItemProperty(item, 'is_versionable') === '1');
if (window.handleItemChange) {
	if (_isVers) {
		const isRelationship = (aras.getItemProperty(item, 'is_relationship') == '1');
		const versioningDiscipline = isRelationship ? 'BaselineVersioningDiscipline' : '0';
		handleItemChange('manual_versioning', versioningDiscipline);
	} else {
		handleItemChange('manual_versioning', '');
		aras.setItemPropertyAttribute(item, 'manual_versioning', 'is_null', '1');
	}
}
if (_mv_chb) {
	_mv_chb.setDisabled(!_isVers);
	_mv_chb.setReadOnly(!_isVers);
}
